      }
    },
    {
      "id": "classify",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Classify Email"
      },
      "inputs": {
        "errorHandlingEnabled": true,
        "script": "const emailData = $vars.emailReceived1.output;\nconst subject = (emailData.subject || emailData.Subject || '').toLowerCase();\nconst body = (emailData.body || emailData.Body || emailData.bodyPreview || '').toLowerCase();\nconst sender = emailData.from || emailData.sender || emailData.From || '';\nconst text = subject + ' ' + body;\nconst urgentKeywords = ['urgent', 'critical', 'emergency', 'asap', 'immediately', 'down', 'outage', 'broken', 'not working', 'help needed', 'p0'];\nconst matchedKeyword = urgentKeywords.find(function(kw) { return text.includes(kw); });\nconst isUrgent = !!matchedKeyword;\nreturn {\n  isUrgent: isUrgent,\n  reason: isUrgent ? 'Matched keyword: ' + matchedKeyword : 'No urgency keywords detected',\n  subject: emailData.subject || emailData.Subject || '(no subject)',\n  sender: sender\n};"
      }
    },
    {
      "id": "isUrgent",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Is Urgent?"
      },
      "inputs": {
        "expression": "$vars.classify.output.isUrgent === true",
        "trueLabel": "Urgent",
        "falseLabel": "Normal"
      }
    },
    {
      "id": "slackAlertToTeam1",
      "type": "uipath.connector.uipath-salesforce-slack.send-message-to-channel",
      "typeVersion": "1.0.0",
