const subject = (emailData.subject || emailData.Subject || '').toLowerCase();
const body = (emailData.body || emailData.Body || emailData.bodyPreview || '').toLowerCase();
const sender = emailData.from || emailData.sender || emailData.From || '';
const text = subject + ' ' + body;
const urgentKeywords = ['urgent', 'critical', 'emergency', 'asap', 'immediately', 'down', 'outage', 'broken', 'not working', 'help needed', 'p0'];
const matchedKeyword = urgentKeywords.find(function(kw) { return text.includes(kw); });
const isUrgent = !!matchedKeyword;
return {
  isUrgent: isUrgent,
  reason: isUrgent ? 'Matched keyword: ' + matchedKeyword : 'No urgency keywords detected',
  subject: emailData.subject || emailData.Subject || '(no subject)',
  sender: sender
};"

parameters.new_string:
        "script": "const emailData = $vars.emailReceived1.output;
const subject = (emailData.subject || emailData.Subject || '').toLowerCase();
const body = (emailData.body || emailData.Body || emailData.bodyPreview || '').toLowerCase();
const sender = emailData.from || emailData.sender || emailData.From || '';
const senderDomain = (sender.split('@')[1] || '').toLowerCase().trim();
const text = subject + ' ' + body;

// Urgency detection
const urgentKeywords = ['urgent', 'critical', 'emergency', 'asap', 'immediately', 'down', 'outage', 'broken', 'not working', 'help needed', 'p0'];
const matchedKeyword = urgentKeywords.find(function(kw) { return text.includes(kw); });
const isUrgent = !!matchedKeyword;

// VIP client detection — important enterprise/partner domains
// Update this list as your client base grows
const vipDomains = [
  'acmecorp.com',
  'globaltech.com',
  'enterprise-partner.com',
  'bigsystems.io',
  'keyaccount.net',
  'strategicclient.com',
  'platinumpartner.co',
  'premiumcustomer.org'
];
const isVip = vipDomains.some(function(domain) { return senderDomain === domain; });

return {
  isUrgent: isUrgent,
  isVip: isVip,
  isVipUrgent: isUrgent && isVip,
  reason: isUrgent ? 'Matched keyword: ' + matchedKeyword : 'No urgency keywords detected',
  subject: emailData.subject || emailData.Subject || '(no subject)',
  sender: sender,
  senderDomain: senderDomain
};"

